<h1 class="h">API klíče</h1><div class="sub">Klíč se zobrazí pouze při vytvoření. Ukládá se pouze jeho hash.</div><?php if(!empty($new_key)):?><div class="success"><b>Nový klíč:</b> <code><?=\App\Core\View::e($new_key)?></code> – uložte si ho, znovu se nezobrazí.</div><?php endif;?><div class="card"><form class="row" method="post" action="/settings/api-keys"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><input name="name" placeholder="Název klíče" required><button class="btn primary">Vytvořit API klíč</button></form></div><div class="card" style="margin-top:16px"><table class="table"><tr><th>Název</th><th>Vytvořeno</th><th>Naposledy použito</th></tr><?php foreach($keys as $k):?><tr><td><?=\App\Core\View::e($k['name'])?></td><td><?=\App\Core\View::e($k['created_at'])?></td><td><?=\App\Core\View::e($k['last_used_at']??'—')?></td></tr><?php endforeach;?></table></div>